(() => {
  'use strict';

  const WIDTH = 4;
  const HEIGHT = 3;
  const END_TICK = 2700;
  const CHARGE_TICKS = 45;

  function random(seed) {
    let value = (seed >>> 0) || 1;
    return function () {
      value = (value + 0x6D2B79F5) >>> 0;
      let t = value;
      t = Math.imul(t ^ (t >>> 15), t | 1);
      t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
      return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
    };
  }

  function index(x, y) { return y * WIDTH + x; }

  function connected(state) {
    let y = 1;
    for (let x = 0; x < WIDTH; x += 1) {
      y += state.board[index(x, y)].outlet;
      if (y < 0 || y >= HEIGHT) return { hit: false, leak: true, end: y };
    }
    return { hit: y === state.target, leak: false, end: y };
  }

  function makeBoard(state) {
    const chapter = state.circuits;
    const rng = random((state.seed + 1013904223 * (state.boardNumber + 1)) >>> 0);
    const target = Math.floor(rng() * HEIGHT);
    const desired = [];
    let row = 1;
    for (let x = 0; x < WIDTH; x += 1) {
      let next;
      if (x === WIDTH - 1) {
        next = target;
      } else {
        const options = [];
        for (let d = -1; d <= 1; d += 1) if (row + d >= 0 && row + d < HEIGHT) options.push(row + d);
        next = options[Math.floor(rng() * options.length)];
      }
      desired.push({ x: x, y: row, outlet: next - row });
      row = next;
    }
    const board = [];
    for (let y = 0; y < HEIGHT; y += 1) {
      for (let x = 0; x < WIDTH; x += 1) board.push({ outlet: Math.floor(rng() * 3) - 1 });
    }
    for (let i = 0; i < desired.length; i += 1) {
      const p = desired[i];
      board[index(p.x, p.y)].outlet = p.outlet;
    }
    state.board = board;
    state.target = target;
    // The first relay is a gentle one-turn discovery; later relays disturb more links.
    const disturbances = Math.min(4, 1 + chapter);
    for (let i = 0; i < disturbances; i += 1) {
      const p = desired[(i * 2 + chapter) % desired.length];
      const tile = board[index(p.x, p.y)];
      tile.outlet = tile.outlet === 1 ? -1 : tile.outlet + 1;
    }
    // A board may have an alternate route after a disturbance. Deterministically spoil it.
    if (connected(state).hit) {
      const tile = board[index(desired[0].x, desired[0].y)];
      tile.outlet = tile.outlet === 0 ? 1 : 0;
    }
  }

  function create(seed) {
    const state = {
      seed: (Number(seed) || 23) >>> 0,
      tick: 0,
      score: 0,
      circuits: 0,
      rotations: 0,
      cursor: { x: 0, y: 1 },
      target: 1,
      board: [],
      boardNumber: 0,
      charge: 0,
      pulse: 0,
      particles: [],
      prevAction: false,
      pointerHeld: false,
      prevX: 0,
      prevY: 0,
      navWaitX: 0,
      navWaitY: 0,
      terminal: false
    };
    makeBoard(state);
    return state;
  }

  function rotate(state, x, y) {
    const tile = state.board[index(x, y)];
    tile.outlet = tile.outlet === 1 ? -1 : tile.outlet + 1;
    state.rotations += 1;
  }

  function navigate(state, axis, value) {
    if (!value) return;
    if (axis === 'x') state.cursor.x = Math.max(0, Math.min(WIDTH - 1, state.cursor.x + value));
    else state.cursor.y = Math.max(0, Math.min(HEIGHT - 1, state.cursor.y + value));
  }

  function handleAxis(state, name, value) {
    const prevName = name === 'x' ? 'prevX' : 'prevY';
    const waitName = name === 'x' ? 'navWaitX' : 'navWaitY';
    if (!value) { state[waitName] = 0; state[prevName] = 0; return; }
    if (value !== state[prevName]) {
      navigate(state, name, value);
      state[waitName] = 12;
    } else if (state[waitName] <= 0) {
      navigate(state, name, value);
      state[waitName] = 12;
    } else state[waitName] -= 1;
    state[prevName] = value;
  }

  function step(state, input) {
    if (state.terminal) return state;
    const safe = input || {};
    handleAxis(state, 'x', safe.x === 1 ? 1 : safe.x === -1 ? -1 : 0);
    handleAxis(state, 'y', safe.y === 1 ? 1 : safe.y === -1 ? -1 : 0);

    const hasPointer = !!safe.pointer;
    if (hasPointer && !state.pointerHeld) {
      const px = Math.max(0, Math.min(0.9999, Number(safe.pointer.x) || 0));
      const py = Math.max(0, Math.min(0.9999, Number(safe.pointer.y) || 0));
      if (px >= 0.08 && px <= 0.92 && py >= 0.23 && py <= 0.75) {
        const x = Math.min(WIDTH - 1, Math.floor((px - 0.08) / 0.84 * WIDTH));
        const y = Math.min(HEIGHT - 1, Math.floor((py - 0.23) / 0.52 * HEIGHT));
        state.cursor.x = x;
        state.cursor.y = y;
        rotate(state, x, y);
      }
    } else if (!hasPointer && safe.action && !state.prevAction) {
      rotate(state, state.cursor.x, state.cursor.y);
    }
    state.pointerHeld = hasPointer;
    state.prevAction = !!safe.action;

    const route = connected(state);
    state.charge = route.hit ? Math.min(CHARGE_TICKS, state.charge + 1) : 0;
    if (state.charge >= CHARGE_TICKS) {
      state.circuits += 1;
      state.score += 100 + Math.floor((END_TICK - state.tick) / 90);
      state.pulse = 36;
      state.particles = [];
      for (let i = 0; i < 18; i += 1) state.particles.push({ a: i * 0.349, life: 32 + (i % 4) * 5 });
      state.boardNumber += 1;
      state.charge = 0;
      makeBoard(state);
    }
    if (state.pulse > 0) state.pulse -= 1;
    state.particles = state.particles.filter(function (p) { p.life -= 1; return p.life > 0; });
    state.tick += 1;
    if (state.tick >= END_TICK) state.terminal = true;
    return state;
  }

  function observe(state) {
    return {
      tick: state.tick,
      score: state.score,
      progress: Math.min(100, Math.floor(state.tick * 100 / END_TICK)),
      interactions: state.rotations + state.circuits,
      entities: state.particles.length + 12
    };
  }

  function terminal(state) { return !!state.terminal; }
  globalThis.PrismRelayCore = { create: create, step: step, observe: observe, terminal: terminal };
}());

(() => {
  'use strict';
  fetch('./manifest.json').then(function (response) { return response.json(); }).then(function (metadata) {
    PlayJoltGameKit.create({
      core: globalThis.PrismRelayCore,
      draw: globalThis.PrismRelayView.draw,
      canvas: document.querySelector('[data-game-canvas]'),
      metadata: metadata
    });
  }).catch(function () {
    const error = document.querySelector('[data-game-error]');
    error.hidden = false;
    error.textContent = 'Unable to prepare Prism Relay.';
  });
}());

(() => {
  'use strict';
  function line(ctx, a, b, color, width) {
    ctx.strokeStyle = color; ctx.lineWidth = width; ctx.beginPath(); ctx.moveTo(a.x, a.y); ctx.lineTo(b.x, b.y); ctx.stroke();
  }
  function draw(ctx, snapshot, size) {
    const w = size.width, h = size.height, s = snapshot.state;
    const sx = w * 0.08, sy = h * 0.23, bw = w * 0.84, bh = h * 0.52, cw = bw / 4, ch = bh / 3;
    const route = []; let row = 1; let leaking = false;
    route.push({ x: sx - cw * .34, y: sy + (row + .5) * ch });
    for (let x = 0; x < 4; x += 1) {
      const tile = s.board[row * 4 + x];
      const center = { x: sx + (x + .5) * cw, y: sy + (row + .5) * ch };
      route.push(center); row += tile.outlet;
      const exit = { x: sx + (x + 1) * cw, y: sy + (row + .5) * ch };
      route.push(exit);
      if (row < 0 || row > 2) { leaking = true; break; }
    }
    ctx.clearRect(0, 0, w, h);
    const bg = ctx.createLinearGradient(0, 0, w, h); bg.addColorStop(0, '#071229'); bg.addColorStop(1, '#11183d'); ctx.fillStyle = bg; ctx.fillRect(0, 0, w, h);
    ctx.fillStyle = '#dffaff'; ctx.font = '700 ' + Math.max(21, w * .058) + 'px system-ui'; ctx.textAlign = 'left'; ctx.fillText('PRISM RELAY', sx, h * .09);
    ctx.fillStyle = '#92afc8'; ctx.font = Math.max(11, w * .024) + 'px system-ui'; ctx.fillText('Route light to the marked receiver. Hold it for a full charge.', sx, h * .13);
    const remaining = Math.max(0, Math.ceil((2700 - s.tick) / 60));
    ctx.textAlign = 'right'; ctx.fillStyle = '#f8c66b'; ctx.font = '700 ' + Math.max(18, w * .045) + 'px system-ui'; ctx.fillText(remaining + 's', sx + bw, h * .09);
    ctx.fillStyle = '#a9d8d9'; ctx.font = Math.max(12, w * .027) + 'px system-ui'; ctx.fillText('CIRCUITS  ' + s.circuits + '   SCORE  ' + s.score, sx + bw, h * .13);

    ctx.fillStyle = 'rgba(118,180,222,.07)'; ctx.fillRect(sx, sy, bw, bh);
    ctx.strokeStyle = 'rgba(157,228,249,.23)'; ctx.lineWidth = 1; ctx.strokeRect(sx, sy, bw, bh);
    for (let y = 0; y < 3; y += 1) for (let x = 0; x < 4; x += 1) {
      const cx = sx + (x + .5) * cw, cy = sy + (y + .5) * ch, selected = x === s.cursor.x && y === s.cursor.y;
      ctx.save(); ctx.translate(cx, cy);
      ctx.fillStyle = selected ? 'rgba(101,230,219,.18)' : 'rgba(142,205,241,.10)';
      ctx.strokeStyle = selected ? '#8dfff0' : 'rgba(194,234,255,.5)'; ctx.lineWidth = selected ? 3 : 1;
      ctx.beginPath(); ctx.moveTo(-cw*.29, 0); ctx.lineTo(0, -ch*.30); ctx.lineTo(cw*.29, 0); ctx.lineTo(0, ch*.30); ctx.closePath(); ctx.fill(); ctx.stroke();
      const out = s.board[y * 4 + x].outlet;
      const ex = cw * .32, ey = out * ch * .30;
      line(ctx, {x: -cw*.12,y:0}, {x:ex,y:ey}, '#b9f9f1', 2);
      ctx.fillStyle = '#b9f9f1'; ctx.beginPath(); ctx.arc(ex, ey, 4, 0, Math.PI*2); ctx.fill();
      ctx.restore();
    }
    // receiver rail
    for (let y = 0; y < 3; y += 1) {
      const rx = sx + bw + cw*.12, ry = sy + (y+.5)*ch;
      ctx.strokeStyle = y === s.target ? '#77ffdb' : 'rgba(125,177,203,.3)'; ctx.lineWidth = y === s.target ? 4 : 2;
      ctx.beginPath(); ctx.arc(rx, ry, ch*.19, 0, Math.PI*2); ctx.stroke();
      if (y === s.target) { ctx.fillStyle = '#77ffdb'; ctx.beginPath(); ctx.arc(rx,ry,4,0,Math.PI*2); ctx.fill(); }
    }
    ctx.shadowBlur = 14; ctx.shadowColor = leaking ? '#f49d62' : '#73f5d6';
    for (let i = 0; i < route.length - 1; i += 1) line(ctx, route[i], route[i+1], leaking ? '#dc986f' : '#6ce4cf', s.charge ? 6 : 3);
    ctx.shadowBlur = 0;
    const emitter = route[0]; ctx.fillStyle = '#ffc66b'; ctx.beginPath(); ctx.arc(emitter.x, emitter.y, 9, 0, Math.PI*2); ctx.fill();
    const arcX = sx + bw + cw*.12, arcY = sy + (s.target+.5)*ch;
    ctx.strokeStyle = '#ffe08a'; ctx.lineWidth = 3; ctx.beginPath(); ctx.arc(arcX, arcY, ch*.28, -Math.PI/2, -Math.PI/2 + Math.PI*2*(s.charge/45)); ctx.stroke();
    if (s.pulse) { ctx.fillStyle = 'rgba(111,255,218,' + (s.pulse/70) + ')'; ctx.beginPath(); ctx.arc(arcX,arcY,ch*(.25+(36-s.pulse)*.018),0,Math.PI*2); ctx.fill(); }
    ctx.textAlign = 'center'; ctx.fillStyle = '#b2cadb'; ctx.font = Math.max(11,w*.023)+'px system-ui';
    ctx.fillText('Tap a facet to rotate  •  arrows select + Space rotates', w/2, h*.84);
    ctx.fillStyle = '#6686a5'; ctx.fillText(s.circuits === 0 ? 'SPARK' : s.circuits === 1 ? 'SURGE' : 'SPECTRUM', w/2, h*.885);
    if (s.terminal) {
      ctx.fillStyle='rgba(3,10,28,.78)'; ctx.fillRect(0,0,w,h); ctx.fillStyle=s.circuits>=3?'#80ffe0':'#ffd18a'; ctx.font='700 '+Math.max(27,w*.07)+'px system-ui';
      ctx.fillText(s.circuits>=3?'RELAY COMPLETE':'RELAY INCOMPLETE',w/2,h*.43); ctx.fillStyle='#ecf8ff'; ctx.font=Math.max(16,w*.038)+'px system-ui'; ctx.fillText(s.circuits+' circuits lit  •  '+s.score+' points',w/2,h*.50); ctx.fillStyle='#9db9d0'; ctx.font=Math.max(12,w*.027)+'px system-ui'; ctx.fillText('Use Play Again below to replay this seed.',w/2,h*.56);
    }
  }
  globalThis.PrismRelayView = { draw: draw };
}());

(() => {
  'use strict';

  const COLS = 4;
  const ROWS = 3;
  const RUN_TICKS = 2700;
  const HOLD_TICKS = 45;

  function at(x, y) { return y * COLS + x; }

  function rngFor(seed) {
    let n = (seed >>> 0) || 23;
    return function () {
      n = (n + 0x6d2b79f5) >>> 0;
      let t = n;
      t = Math.imul(t ^ (t >>> 15), t | 1);
      t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
      return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
    };
  }

  function clamp(value, low, high) {
    return Math.max(low, Math.min(high, value));
  }

  function trace(state) {
    let row = 1;
    const points = [{ x: -1, y: row }];
    for (let x = 0; x < COLS; x += 1) {
      points.push({ x: x, y: row });
      const tile = state.board[at(x, row)];
      row += tile.outlet;
      points.push({ x: x + 1, y: row });
      if (row < 0 || row >= ROWS) {
        return { hit: false, leak: true, row: row, points: points };
      }
    }
    return { hit: row === state.target, leak: false, row: row, points: points };
  }

  function outletChoices(row) {
    const choices = [];
    for (let d = -1; d <= 1; d += 1) {
      if (row + d >= 0 && row + d < ROWS) choices.push(d);
    }
    return choices;
  }

  function makeBoard(state) {
    const rand = rngFor((state.seed + Math.imul(state.boardNumber + 1, 1103515245)) >>> 0);
    const solution = [];
    let row = 1;

    for (let x = 0; x < COLS; x += 1) {
      const options = outletChoices(row);
      const outlet = options[Math.floor(rand() * options.length)];
      solution.push({ x: x, y: row, outlet: outlet });
      row += outlet;
    }

    state.target = row;
    state.board = [];
    for (let y = 0; y < ROWS; y += 1) {
      for (let x = 0; x < COLS; x += 1) {
        state.board.push({ outlet: Math.floor(rand() * 3) - 1 });
      }
    }
    for (let i = 0; i < solution.length; i += 1) {
      const p = solution[i];
      state.board[at(p.x, p.y)].outlet = p.outlet;
    }

    const disturbances = Math.min(COLS, 1 + Math.min(3, state.circuits));
    for (let i = 0; i < disturbances; i += 1) {
      const p = solution[(i * 3 + state.boardNumber) % solution.length];
      const tile = state.board[at(p.x, p.y)];
      tile.outlet = tile.outlet === 1 ? -1 : tile.outlet + 1;
    }

    /* Always begin uncharged: this prevents passive score farming. */
    if (trace(state).hit) {
      const p = solution[0];
      const tile = state.board[at(p.x, p.y)];
      tile.outlet = tile.outlet === 0 ? 1 : 0;
    }
  }

  function create(seed) {
    const state = {
      seed: (Number(seed) || 23) >>> 0,
      tick: 0,
      score: 0,
      circuits: 0,
      rotations: 0,
      cursor: { x: 0, y: 1 },
      target: 1,
      board: [],
      boardNumber: 0,
      charge: 0,
      pulse: 0,
      particles: [],
      previousAction: false,
      pointerDown: false,
      heldX: 0,
      heldY: 0,
      repeatX: 0,
      repeatY: 0,
      terminal: false
    };
    makeBoard(state);
    return state;
  }

  function rotate(state, x, y) {
    const tile = state.board[at(x, y)];
    tile.outlet = tile.outlet === 1 ? -1 : tile.outlet + 1;
    state.rotations += 1;
  }

  function moveAxis(state, axis, value) {
    const heldName = axis === 'x' ? 'heldX' : 'heldY';
    const repeatName = axis === 'x' ? 'repeatX' : 'repeatY';
    if (!value) {
      state[heldName] = 0;
      state[repeatName] = 0;
      return;
    }
    if (state[heldName] !== value) {
      state.cursor[axis] = clamp(state.cursor[axis] + value, 0, axis === 'x' ? COLS - 1 : ROWS - 1);
      state[repeatName] = 12;
    } else if (state[repeatName] <= 0) {
      state.cursor[axis] = clamp(state.cursor[axis] + value, 0, axis === 'x' ? COLS - 1 : ROWS - 1);
      state[repeatName] = 12;
    } else {
      state[repeatName] -= 1;
    }
    state[heldName] = value;
  }

  function pointerTile(pointer) {
    const px = Number(pointer.x);
    const py = Number(pointer.y);
    if (!Number.isFinite(px) || !Number.isFinite(py)) return null;
    if (px < 0.08 || px > 0.92 || py < 0.23 || py > 0.75) return null;
    return {
      x: clamp(Math.floor((px - 0.08) * COLS / 0.84), 0, COLS - 1),
      y: clamp(Math.floor((py - 0.23) * ROWS / 0.52), 0, ROWS - 1)
    };
  }

  function burst(state) {
    state.pulse = 36;
    state.particles = [];
    for (let i = 0; i < 20; i += 1) {
      state.particles.push({ angle: i * Math.PI * 2 / 20, life: 24 + (i % 5) * 3 });
    }
  }

  function step(state, input) {
    if (state.terminal) return state;
    const control = input || {};
    const x = control.x === 1 ? 1 : control.x === -1 ? -1 : 0;
    const y = control.y === 1 ? 1 : control.y === -1 ? -1 : 0;
    moveAxis(state, 'x', x);
    moveAxis(state, 'y', y);

    const hasPointer = control.pointer !== null && typeof control.pointer === 'object';
    if (hasPointer && !state.pointerDown) {
      const chosen = pointerTile(control.pointer);
      if (chosen) {
        state.cursor.x = chosen.x;
        state.cursor.y = chosen.y;
        rotate(state, chosen.x, chosen.y);
      }
    } else if (!hasPointer && control.action && !state.previousAction) {
      rotate(state, state.cursor.x, state.cursor.y);
    }
    state.pointerDown = hasPointer;
    state.previousAction = !!control.action;

    const route = trace(state);
    state.charge = route.hit ? Math.min(HOLD_TICKS, state.charge + 1) : 0;
    if (state.charge === HOLD_TICKS) {
      state.circuits += 1;
      state.score += 100 + Math.floor((RUN_TICKS - state.tick) / 90);
      state.boardNumber += 1;
      state.charge = 0;
      burst(state);
      makeBoard(state);
    }

    if (state.pulse > 0) state.pulse -= 1;
    for (let i = state.particles.length - 1; i >= 0; i -= 1) {
      state.particles[i].life -= 1;
      if (state.particles[i].life <= 0) state.particles.splice(i, 1);
    }

    state.tick += 1;
    if (state.tick >= RUN_TICKS) state.terminal = true;
    return state;
  }

  function observe(state) {
    return {
      tick: state.tick,
      score: state.score,
      progress: Math.min(100, Math.floor(state.tick * 100 / RUN_TICKS)),
      interactions: state.rotations + state.circuits,
      entities: 12 + state.particles.length
    };
  }

  function terminal(state) { return state.terminal === true; }

  globalThis.PrismRelayCore = {
    create: create,
    step: step,
    observe: observe,
    terminal: terminal
  };
}());

(() => {
  'use strict';

  function showError() {
    const node = document.querySelector('[data-game-error]');
    if (node) {
      node.hidden = false;
      node.textContent = 'Unable to prepare Prism Relay.';
    }
  }

  fetch('./manifest.json')
    .then(function (response) {
      if (!response.ok) throw new Error('manifest');
      return response.json();
    })
    .then(function (metadata) {
      const canvas = document.querySelector('[data-game-canvas]');
      if (!canvas || !globalThis.PlayJoltGameKit || !globalThis.PrismRelayCore || !globalThis.PrismRelayView) {
        throw new Error('runtime');
      }
      PlayJoltGameKit.create({
        core: globalThis.PrismRelayCore,
        draw: globalThis.PrismRelayView.draw,
        canvas: canvas,
        metadata: metadata
      });
    })
    .catch(showError);
}());

(() => {
  'use strict';

  function pathStroke(ctx, points, color, width) {
    if (points.length < 2) return;
    ctx.beginPath();
    ctx.moveTo(points[0].x, points[0].y);
    for (let i = 1; i < points.length; i += 1) ctx.lineTo(points[i].x, points[i].y);
    ctx.strokeStyle = color;
    ctx.lineWidth = width;
    ctx.stroke();
  }

  function draw(ctx, snapshot, size) {
    const state = snapshot.state;
    const w = size.width;
    const h = size.height;
    const left = w * 0.08;
    const top = h * 0.23;
    const boardW = w * 0.84;
    const boardH = h * 0.52;
    const cellW = boardW / 4;
    const cellH = boardH / 3;
    const route = [];
    let row = 1;
    let leak = false;

    route.push({ x: left - cellW * 0.32, y: top + (row + 0.5) * cellH });
    for (let x = 0; x < 4; x += 1) {
      route.push({ x: left + (x + 0.5) * cellW, y: top + (row + 0.5) * cellH });
      const tile = state.board[row * 4 + x];
      row += tile.outlet;
      route.push({ x: left + (x + 1) * cellW, y: top + (row + 0.5) * cellH });
      if (row < 0 || row > 2) {
        leak = true;
        break;
      }
    }

    const background = ctx.createLinearGradient(0, 0, w, h);
    background.addColorStop(0, '#061126');
    background.addColorStop(1, '#151641');
    ctx.fillStyle = background;
    ctx.fillRect(0, 0, w, h);

    ctx.textAlign = 'left';
    ctx.fillStyle = '#e6fbff';
    ctx.font = '700 ' + Math.max(22, w * 0.058) + 'px system-ui';
    ctx.fillText('PRISM RELAY', left, h * 0.09);
    ctx.fillStyle = '#9ab8cf';
    ctx.font = Math.max(11, w * 0.024) + 'px system-ui';
    ctx.fillText('Route light to the marked receiver, then hold the circuit.', left, h * 0.13);

    const seconds = Math.max(0, Math.ceil((2700 - state.tick) / 60));
    ctx.textAlign = 'right';
    ctx.fillStyle = '#ffd071';
    ctx.font = '700 ' + Math.max(18, w * 0.045) + 'px system-ui';
    ctx.fillText(seconds + 's', left + boardW, h * 0.09);
    ctx.fillStyle = '#b8e9df';
    ctx.font = Math.max(12, w * 0.027) + 'px system-ui';
