(() => {
  'use strict';

  const COLS = 4;
  const ROWS = 3;
  const RUN_TICKS = 2700;
  const CHARGE_TICKS = 45;

  function indexOf(x, y) {
    return y * COLS + x;
  }

  function cap(value, min, max) {
    return Math.max(min, Math.min(max, value));
  }

  function random(seed) {
    let value = (seed >>> 0) || 23;
    return function () {
      value = (value + 0x6D2B79F5) >>> 0;
      let mixed = value;
      mixed = Math.imul(mixed ^ (mixed >>> 15), mixed | 1);
      mixed ^= mixed + Math.imul(mixed ^ (mixed >>> 7), mixed | 61);
      return ((mixed ^ (mixed >>> 14)) >>> 0) / 4294967296;
    };
  }

  function availableOutlets(row) {
    const result = [];
    for (let direction = -1; direction <= 1; direction += 1) {
      if (row + direction >= 0 && row + direction < ROWS) result.push(direction);
    }
    return result;
  }

  function trace(state) {
    let row = 1;
    for (let x = 0; x < COLS; x += 1) {
      row += state.board[indexOf(x, row)].outlet;
      if (row < 0 || row >= ROWS) return { connected: false, leak: true, row: row };
    }
    return { connected: row === state.target, leak: false, row: row };
  }

  function buildBoard(state) {
    const rand = random((state.seed + Math.imul(state.boardNumber + 1, 1103515245)) >>> 0);
    const route = [];
    let row = 1;
    let x;

    for (x = 0; x < COLS; x += 1) {
      const choices = availableOutlets(row);
      const outlet = choices[Math.floor(rand() * choices.length)];
      route.push({ x: x, y: row, outlet: outlet });
      row += outlet;
    }
    state.target = row;
    state.board = [];
    for (let y = 0; y < ROWS; y += 1) {
      for (x = 0; x < COLS; x += 1) {
        state.board.push({ outlet: Math.floor(rand() * 3) - 1 });
      }
    }
    for (let i = 0; i < route.length; i += 1) {
      const piece = route[i];
      state.board[indexOf(piece.x, piece.y)].outlet = piece.outlet;
    }

    const scrambled = Math.min(COLS, 1 + Math.min(state.circuits, 3));
    for (let i = 0; i < scrambled; i += 1) {
      const piece = route[(state.boardNumber + i * 3) % route.length];
      const tile = state.board[indexOf(piece.x, piece.y)];
      tile.outlet = tile.outlet === 1 ? -1 : tile.outlet + 1;
    }
    if (trace(state).connected) {
      const first = route[0];
      const tile = state.board[indexOf(first.x, first.y)];
      tile.outlet = tile.outlet === 0 ? 1 : 0;
    }
  }

  function create(seed) {
    const state = {
      seed: (Number(seed) || 23) >>> 0,
      tick: 0,
      score: 0,
      circuits: 0,
      rotations: 0,
      cursor: { x: 0, y: 1 },
      board: [],
      boardNumber: 0,
      target: 1,
      charge: 0,
      pulse: 0,
      particles: [],
      previousAction: false,
      pointerWasDown: false,
      ignorePointerReleaseAction: false,
      heldX: 0,
      heldY: 0,
      repeatX: 0,
      repeatY: 0,
      terminal: false
    };
    buildBoard(state);
    return state;
  }

  function rotate(state, x, y) {
    const tile = state.board[indexOf(x, y)];
    tile.outlet = tile.outlet === 1 ? -1 : tile.outlet + 1;
    state.rotations += 1;
  }

  function move(state, axis, direction) {
    const held = axis === 'x' ? 'heldX' : 'heldY';
    const repeat = axis === 'x' ? 'repeatX' : 'repeatY';
    const maximum = axis === 'x' ? COLS - 1 : ROWS - 1;
    if (direction === 0) {
      state[held] = 0;
      state[repeat] = 0;
      return;
    }
    if (state[held] !== direction) {
      state.cursor[axis] = cap(state.cursor[axis] + direction, 0, maximum);
      state[repeat] = 12;
    } else if (state[repeat] <= 0) {
      state.cursor[axis] = cap(state.cursor[axis] + direction, 0, maximum);
      state[repeat] = 12;
    } else {
      state[repeat] -= 1;
    }
    state[held] = direction;
  }

  function hitTest(pointer) {
    const x = Number(pointer.x);
    const y = Number(pointer.y);
    if (!Number.isFinite(x) || !Number.isFinite(y)) return null;
    if (x < 0.08 || x > 0.92 || y < 0.23 || y > 0.75) return null;
    return {
      x: cap(Math.floor((x - 0.08) * COLS / 0.84), 0, COLS - 1),
      y: cap(Math.floor((y - 0.23) * ROWS / 0.52), 0, ROWS - 1)
    };
  }

  function makeBurst(state) {
    state.pulse = 36;
    state.particles = [];
    for (let i = 0; i < 20; i += 1) {
      state.particles.push({ angle: i * Math.PI * 2 / 20, life: 24 + (i % 5) * 3 });
    }
  }

  function step(state, input) {
    if (state.terminal) return state;
    const control = input || {};
    const horizontal = control.x === 1 ? 1 : control.x === -1 ? -1 : 0;
    const vertical = control.y === 1 ? 1 : control.y === -1 ? -1 : 0;
    move(state, 'x', horizontal);
    move(state, 'y', vertical);

    const hasPointer = control.pointer !== null && typeof control.pointer === 'object';
    if (hasPointer && !state.pointerWasDown) {
      const tile = hitTest(control.pointer);
      if (tile) {
        state.cursor.x = tile.x;
        state.cursor.y = tile.y;
        rotate(state, tile.x, tile.y);
      }
      state.ignorePointerReleaseAction = true;
    } else if (!hasPointer && control.action && !state.previousAction && !state.ignorePointerReleaseAction) {
      rotate(state, state.cursor.x, state.cursor.y);
    }
    if (!hasPointer) state.ignorePointerReleaseAction = false;
    state.pointerWasDown = hasPointer;
    state.previousAction = !!control.action;

    const result = trace(state);
    state.charge = result.connected ? Math.min(CHARGE_TICKS, state.charge + 1) : 0;
    if (state.charge === CHARGE_TICKS) {
      state.circuits += 1;
      state.score += 100 + Math.floor((RUN_TICKS - state.tick) / 90);
      state.boardNumber += 1;
      state.charge = 0;
      makeBurst(state);
      buildBoard(state);
    }

    if (state.pulse > 0) state.pulse -= 1;
    for (let i = state.particles.length - 1; i >= 0; i -= 1) {
      state.particles[i].life -= 1;
      if (state.particles[i].life <= 0) state.particles.splice(i, 1);
    }

    state.tick += 1;
    if (state.tick >= RUN_TICKS) state.terminal = true;
    return state;
  }

  function observe(state) {
    return {
      tick: state.tick,
      score: state.score,
      progress: Math.min(100, Math.floor(state.tick * 100 / RUN_TICKS)),
      interactions: state.rotations + state.circuits,
      entities: 12 + state.particles.length
    };
  }

  function terminal(state) {
    return state.terminal === true;
  }

  globalThis.PrismRelayCore = { create: create, step: step, observe: observe, terminal: terminal };
}());

(() => {
  'use strict';

  function showError() {
    const message = document.querySelector('[data-game-error]');
    if (message) {
      message.hidden = false;
      message.textContent = 'Unable to prepare Prism Relay.';
    }
  }

  fetch('./manifest.json')
    .then(function (response) {
      if (!response.ok) throw new Error('manifest unavailable');
      return response.json();
    })
    .then(function (metadata) {
      const canvas = document.querySelector('[data-game-canvas]');
      if (!canvas || !globalThis.PlayJoltGameKit || !globalThis.PrismRelayCore || !globalThis.PrismRelayView) {
        throw new Error('game runtime unavailable');
      }
      globalThis.PlayJoltGameKit.create({
        core: globalThis.PrismRelayCore,
        draw: globalThis.PrismRelayView.draw,
        canvas: canvas,
        metadata: metadata
      });
    })
    .catch(showError);
}());

