@media (min-width: 900px) and (max-height: 850px) { canvas { max-height: 70vh; aspect-ratio: 1.15 / 1; } }
@media (max-width: 420px) { .game-shell { padding: 8px; } .controls button { padding: 9px 11px; } .readout { font-size: 12px; } }

(function () {
  'use strict';

  var COLS = 4;
  var ROWS = 3;
  var RUN_TICKS = 2700;
  var CHARGE_TICKS = 45;

  function indexOf(x, y) {
    return y * COLS + x;
  }

  function clamp(value, low, high) {
    return Math.max(low, Math.min(high, value));
  }

  function makeRandom(seed) {
    var value = (seed >>> 0) || 23;
    return function () {
      var mixed;
      value = (value + 0x6D2B79F5) >>> 0;
      mixed = value;
      mixed = Math.imul(mixed ^ (mixed >>> 15), mixed | 1);
      mixed ^= mixed + Math.imul(mixed ^ (mixed >>> 7), mixed | 61);
      return ((mixed ^ (mixed >>> 14)) >>> 0) / 4294967296;
    };
  }

  function outletChoices(row) {
    var choices = [];
    var direction;
    for (direction = -1; direction <= 1; direction += 1) {
      if (row + direction >= 0 && row + direction < ROWS) choices.push(direction);
    }
    return choices;
  }

  function trace(state) {
    var row = 1;
    var x;
    var tile;
    for (x = 0; x < COLS; x += 1) {
      tile = state.board[indexOf(x, row)];
      row += tile.outlet;
      if (row < 0 || row >= ROWS) return { connected: false, leak: true, row: row };
    }
    return { connected: row === state.target, leak: false, row: row };
  }

  function buildBoard(state) {
    var random = makeRandom((state.seed + Math.imul(state.boardNumber + 1, 1103515245)) >>> 0);
    var route = [];
    var row = 1;
    var x;
    var y;
    var choices;
    var outlet;
    var i;
    var routePiece;
    var tile;
    var scrambleCount;

    for (x = 0; x < COLS; x += 1) {
      choices = outletChoices(row);
      outlet = choices[Math.floor(random() * choices.length)];
      route.push({ x: x, y: row, outlet: outlet });
      row += outlet;
    }
    state.target = row;
    state.board = [];
    for (y = 0; y < ROWS; y += 1) {
      for (x = 0; x < COLS; x += 1) {
        state.board.push({ outlet: Math.floor(random() * 3) - 1 });
      }
    }
    for (i = 0; i < route.length; i += 1) {
      routePiece = route[i];
      state.board[indexOf(routePiece.x, routePiece.y)].outlet = routePiece.outlet;
    }

    /* The constructed route is intentionally disturbed, never discarded. */
    scrambleCount = Math.min(COLS, 1 + Math.min(state.circuits, 3));
    for (i = 0; i < scrambleCount; i += 1) {
      routePiece = route[(state.boardNumber + i * 3) % route.length];
      tile = state.board[indexOf(routePiece.x, routePiece.y)];
      tile.outlet = tile.outlet === 1 ? -1 : tile.outlet + 1;
    }
    if (trace(state).connected) {
      routePiece = route[0];
      tile = state.board[indexOf(routePiece.x, routePiece.y)];
      tile.outlet = tile.outlet === 0 ? 1 : 0;
    }
  }

  function create(seed) {
    var state = {
      seed: (Number(seed) || 23) >>> 0,
      tick: 0,
      score: 0,
      circuits: 0,
      rotations: 0,
      cursor: { x: 0, y: 1 },
      board: [],
      boardNumber: 0,
      target: 1,
      charge: 0,
      pulse: 0,
      particles: [],
      previousAction: false,
      pointerWasDown: false,
      ignorePointerReleaseAction: false,
      heldX: 0,
      heldY: 0,
      repeatX: 0,
      repeatY: 0,
      terminal: false
    };
    buildBoard(state);
    return state;
  }

  function rotate(state, x, y) {
    var tile = state.board[indexOf(x, y)];
    tile.outlet = tile.outlet === 1 ? -1 : tile.outlet + 1;
    state.rotations += 1;
  }

  function move(state, axis, direction) {
    var held = axis === 'x' ? 'heldX' : 'heldY';
    var repeat = axis === 'x' ? 'repeatX' : 'repeatY';
    var maximum = axis === 'x' ? COLS - 1 : ROWS - 1;
    if (direction === 0) {
      state[held] = 0;
      state[repeat] = 0;
      return;
    }
    if (state[held] !== direction) {
      state.cursor[axis] = clamp(state.cursor[axis] + direction, 0, maximum);
      state[repeat] = 12;
    } else if (state[repeat] <= 0) {
      state.cursor[axis] = clamp(state.cursor[axis] + direction, 0, maximum);
      state[repeat] = 12;
    } else {
      state[repeat] -= 1;
    }
    state[held] = direction;
  }

  function hitTest(pointer) {
    var px = Number(pointer.x);
    var py = Number(pointer.y);
    if (!Number.isFinite(px) || !Number.isFinite(py)) return null;
    if (px < 0.08 || px > 0.92 || py < 0.23 || py > 0.75) return null;
    return {
      x: clamp(Math.floor((px - 0.08) * COLS / 0.84), 0, COLS - 1),
      y: clamp(Math.floor((py - 0.23) * ROWS / 0.52), 0, ROWS - 1)
    };
  }

  function makeBurst(state) {
    var i;
    state.pulse = 36;
    state.particles = [];
    for (i = 0; i < 20; i += 1) {
      state.particles.push({ angle: i * Math.PI * 2 / 20, life: 24 + (i % 5) * 3 });
    }
  }

  function step(state, input) {
    var control = input || {};
    var horizontal;
    var vertical;
    var hasPointer;
    var tapped;
    var result;
    var i;

    if (state.terminal) return state;
    horizontal = control.x === 1 ? 1 : (control.x === -1 ? -1 : 0);
    vertical = control.y === 1 ? 1 : (control.y === -1 ? -1 : 0);
    move(state, 'x', horizontal);
    move(state, 'y', vertical);

    hasPointer = control.pointer !== null && typeof control.pointer === 'object';
    if (hasPointer && !state.pointerWasDown) {
      tapped = hitTest(control.pointer);
      if (tapped) {
        state.cursor.x = tapped.x;
        state.cursor.y = tapped.y;
        rotate(state, tapped.x, tapped.y);
      }
      state.ignorePointerReleaseAction = true;
    } else if (!hasPointer && control.action && !state.previousAction && !state.ignorePointerReleaseAction) {
      rotate(state, state.cursor.x, state.cursor.y);
    }
    if (!hasPointer) state.ignorePointerReleaseAction = false;
    state.pointerWasDown = hasPointer;
    state.previousAction = !!control.action;

    result = trace(state);
    state.charge = result.connected ? Math.min(CHARGE_TICKS, state.charge + 1) : 0;
    if (state.charge === CHARGE_TICKS) {
      state.circuits += 1;
      state.score += 100 + Math.floor((RUN_TICKS - state.tick) / 90);
      state.boardNumber += 1;
      state.charge = 0;
      makeBurst(state);
      buildBoard(state);
    }

    if (state.pulse > 0) state.pulse -= 1;
    for (i = state.particles.length - 1; i >= 0; i -= 1) {
      state.particles[i].life -= 1;
      if (state.particles[i].life <= 0) state.particles.splice(i, 1);
    }
    state.tick += 1;
    if (state.tick >= RUN_TICKS) state.terminal = true;
    return state;
  }

  function observe(state) {
    return {
      tick: state.tick,
      score: state.score,
      progress: Math.min(100, Math.floor(state.tick * 100 / RUN_TICKS)),
      interactions: state.rotations + state.circuits,
      entities: 12 + state.particles.length
    };
  }

  function terminal(state) {
    return state.terminal === true;
  }

  globalThis.PrismRelayCore = {
    create: create,
    step: step,
    observe: observe,
    terminal: terminal
  };
}());

(function () {
  'use strict';

  function showError() {
    var error = document.querySelector('[data-game-error]');
    if (error) {
      error.hidden = false;
      error.textContent = 'Unable to prepare Prism Relay.';
    }
  }

  fetch('./manifest.json')
    .then(function (response) {
      if (!response.ok) throw new Error('Manifest unavailable');
      return response.json();
    })
    .then(function (metadata) {
      var canvas = document.querySelector('[data-game-canvas]');
      if (!canvas || !globalThis.PlayJoltGameKit || !globalThis.PrismRelayCore || !globalThis.PrismRelayView) {
        throw new Error('Game runtime unavailable');
      }
      globalThis.PlayJoltGameKit.create({
        core: globalThis.PrismRelayCore,
        draw: globalThis.PrismRelayView.draw,
        canvas: canvas,
        metadata: metadata
      });
    })
    .catch(showError);
}());

(function () {
  'use strict';

  function routeLine(ctx, points, color, lineWidth) {
    var i;
    if (points.length < 2) return;
    ctx.beginPath();
    ctx.moveTo(points[0].x, points[0].y);
    for (i = 1; i < points.length; i += 1) ctx.lineTo(points[i].x, points[i].y);
    ctx.strokeStyle = color;
    ctx.lineWidth = lineWidth;
    ctx.stroke();
  }

  function draw(ctx, snapshot, size) {
    var state = snapshot.state;
    var width = size.width;
    var height = size.height;
    var left = width * 0.08;
    var top = height * 0.23;
    var boardWidth = width * 0.84;
    var boardHeight = height * 0.52;
    var cellWidth = boardWidth / 4;
    var cellHeight = boardHeight / 3;
    var route = [];
    var row = 1;
    var leaking = false;
    var x;
    var y;
    var cx;
    var cy;
    var outlet;
    var selected;
    var receiverX;
    var receiverY;
    var active;
    var targetY;
    var seconds;
    var particle;
    var distance;
    var sky;

    route.push({ x: left - cellWidth * 0.3, y: top + (row + 0.5) * cellHeight });
    for (x = 0; x < 4; x += 1) {
      route.push({ x: left + (x + 0.5) * cellWidth, y: top + (row + 0.5) * cellHeight });
      row += state.board[row * 4 + x].outlet;
      route.push({ x: left + (x + 1) * cellWidth, y: top + (row + 0.5) * cellHeight });
      if (row < 0 || row > 2) {
        leaking = true;
        break;
      }
    }

    sky = ctx.createLinearGradient(0, 0, width, height);
    sky.addColorStop(0, '#061126');
    sky.addColorStop(1, '#151641');
    ctx.fillStyle = sky;
    ctx.fillRect(0, 0, width, height);

    ctx.textAlign = 'left';
    ctx.fillStyle = '#e8fbff';
    ctx.font = '700 ' + Math.max(22, width * 0.058) + 'px system-ui';
    ctx.fillText('PRISM RELAY', left, height * 0.09);
    ctx.fillStyle = '#9dbbd0';
    ctx.font = Math.max(11, width * 0.024) + 'px system-ui';
    ctx.fillText('Guide light through the prism field.', left, height * 0.13);

    seconds = Math.max(0, Math.ceil((2700 - state.tick) / 60));
    ctx.textAlign = 'right';
    ctx.fillStyle = '#ffd071';
    ctx.font = '700 ' + Math.max(18, width * 0.045) + 'px system-ui';
    ctx.fillText(seconds + 's', left + boardWidth, height * 0.09);
    ctx.fillStyle = '#b8e9df';
    ctx.font = Math.max(12, width * 0.027) + 'px system-ui';
    ctx.fillText('CIRCUITS ' + state.circuits + '   SCORE ' + state.score, left + boardWidth, height * 0.13);

    ctx.fillStyle = 'rgba(119,191,228,0.07)';
    ctx.fillRect(left, top, boardWidth, boardHeight);
    ctx.strokeStyle = 'rgba(180,238,255,0.28)';
    ctx.lineWidth = 1;
    ctx.strokeRect(left, top, boardWidth, boardHeight);

    for (y = 0; y < 3; y += 1) {
      for (x = 0; x < 4; x += 1) {
        cx = left + (x + 0.5) * cellWidth;
        cy = top + (y + 0.5) * cellHeight;
        selected = state.cursor.x === x && state.cursor.y === y;
        outlet = state.board[y * 4 + x].outlet;
        ctx.save();
        ctx.translate(cx, cy);
        ctx.fillStyle = selected ? 'rgba(101,238,219,0.20)' : 'rgba(161,216,248,0.10)';
        ctx.strokeStyle = selected ? '#92fff0' : 'rgba(205,242,255,0.52)';
        ctx.lineWidth = selected ? 3 : 1;
        ctx.beginPath();
        ctx.moveTo(-cellWidth * 0.29, 0);
        ctx.lineTo(0, -cellHeight * 0.30);
        ctx.lineTo(cellWidth * 0.29, 0);
        ctx.lineTo(0, cellHeight * 0.30);
        ctx.closePath();
        ctx.fill();
        ctx.stroke();
        ctx.strokeStyle = '#c2fff5';
        ctx.lineWidth = 2;
        ctx.beginPath();
        ctx.moveTo(-cellWidth * 0.13, 0);
        ctx.lineTo(cellWidth * 0.31, outlet * cellHeight * 0.29);
        ctx.stroke();
        ctx.fillStyle = '#c2fff5';
        ctx.beginPath();
        ctx.arc(cellWidth * 0.31, outlet * cellHeight * 0.29, Math.max(3, width * 0.007), 0, Math.PI * 2);
        ctx.fill();
        ctx.restore();
      }
    }

    receiverX = left + boardWidth + cellWidth * 0.12;
    for (y = 0; y < 3; y += 1) {
      receiverY = top + (y + 0.5) * cellHeight;
      active = y === state.target;
      ctx.strokeStyle = active ? '#79ffe0' : 'rgba(130,185,210,0.32)';
      ctx.lineWidth = active ? 4 : 2;
      ctx.beginPath();
      ctx.arc(receiverX, receiverY, cellHeight * 0.19, 0, Math.PI * 2);
      ctx.stroke();
      if (active) {
        ctx.fillStyle = '#79ffe0';
        ctx.beginPath();
        ctx.arc(receiverX, receiverY, 4, 0, Math.PI * 2);
        ctx.fill();
      }
    }

    ctx.save();
    ctx.shadowBlur = state.charge > 0 ? 18 : 8;
    ctx.shadowColor = leaking ? '#e99365' : '#72f5d8';
    routeLine(ctx, route, leaking ? '#db986d' : '#6ee7d0', state.charge > 0 ? 6 : 3);
    ctx.restore();

    ctx.fillStyle = '#ffca69';
    ctx.beginPath();
    ctx.arc(route[0].x, route[0].y, 9, 0, Math.PI * 2);
    ctx.fill();

    targetY = top + (state.target + 0.5) * cellHeight;
    ctx.strokeStyle = '#ffe391';
    ctx.lineWidth = 3;
    ctx.beginPath();
    ctx.arc(receiverX, targetY, cellHeight * 0.28, -Math.PI / 2, -Math.PI / 2 + Math.PI * 2 * state.charge / 45);
    ctx.stroke();

    if (state.pulse > 0) {
      ctx.fillStyle = 'rgba(111,255,218,' + (state.pulse / 80) + ')';
      ctx.beginPath();
      ctx.arc(receiverX, targetY, cellHeight * (0.25 + (36 - state.pulse) * 0.017), 0, Math.PI * 2);
      ctx.fill();
    }
    for (x = 0; x < state.particles.length; x += 1) {
      particle = state.particles[x];
      distance = (36 - particle.life) * cellHeight * 0.009;
      ctx.fillStyle = 'rgba(157,255,226,' + (particle.life / 42) + ')';
      ctx.beginPath();
      ctx.arc(receiverX + Math.cos(particle.angle) * distance, targetY + Math.sin(particle.angle) * distance, 2, 0, Math.PI * 2);
      ctx.fill();
    }

    ctx.textAlign = 'center';
    ctx.fillStyle = '#b6cedd';
    ctx.font = Math.max(11, width * 0.023) + 'px system-ui';
    ctx.fillText('Tap a prism to rotate  •  arrows select + Space rotates', width / 2, height * 0.84);
    ctx.fillStyle = '#7192b0';
    ctx.fillText(state.circuits === 0 ? 'SPARK' : (state.circuits === 1 ? 'SURGE' : 'SPECTRUM'), width / 2, height * 0.885);

    if (state.terminal) {
      ctx.fillStyle = 'rgba(3,10,28,0.80)';
      ctx.fillRect(0, 0, width, height);
      ctx.textAlign = 'center';
      ctx.fillStyle = state.circuits >= 3 ? '#85ffe2' : '#ffd28d';
      ctx.font = '700 ' + Math.max(26, width * 0.07) + 'px system-ui';
      ctx.fillText(state.circuits >= 3 ? 'RELAY COMPLETE' : 'RELAY INCOMPLETE', width / 2, height * 0.43);
      ctx.fillStyle = '#edfaff';
      ctx.font = Math.max(16, width * 0.038) + 'px system-ui';
      ctx.fillText(state.circuits + ' circuits lit  •  ' + state.score + ' points', width / 2, height * 0.50);
      ctx.fillStyle = '#a8c4d8';
      ctx.font = Math.max(12, width * 0.027) + 'px system-ui';
      ctx.fillText('Select Play Again below to replay this seed.', width / 2, height * 0.56);
    }
  }

  globalThis.PrismRelayView = { draw: draw };
}());

* { box-sizing: border-box; }
html, body { margin: 0; min-height: 100%; background: #050b1d; color: #e9f7ff; font-family: system-ui, sans-serif; }
body { display: flex; justify-content: center; }
.game-shell { width: min(650px, 100%); padding: 12px; overflow: hidden; }
canvas { display: block; width: 100%; aspect-ratio: 5 / 7; max-height: 78vh; background: #071229; border: 1px solid #274568; border-radius: 14px; touch-action: none; outline: none; }
.readout { display: flex; justify-content: space-between; gap: 8px; flex-wrap: wrap; padding: 10px 3px; color: #aac4d8; font-size: 14px; }
.readout b { color: #f2d080; }
.controls { display: flex; flex-wrap: wrap; gap: 8px; }
.controls button { border: 1px solid #4e8a9b; border-radius: 9px; background: #12304b; color: #eaffff; padding: 10px 14px; font: 600 14px system-ui; cursor: pointer; }
.controls button:first-child, .controls button:last-child { background: #176258; border-color: #78d9c5; }
button:focus-visible, canvas:focus-visible { outline: 3px solid #f2c768; outline-offset: 2px; }
[data-game-error] { color: #ffae99; }
@media (min-width: 900px) and (max-height: 850px) { canvas { max-height: 70vh; aspect-ratio: 1.15 / 1; } }
@media (max-width: 420px) { .game-shell { padding: 8px; } .controls button { padding: 9px 11px; } .readout { font-size: 12px; } }
